// general formula for translating a logical address under paging

page_number = logical_address / page_size;      // integer division, drop remainder
offset      = logical_address % page_size;      // whatever the division left behind

frame_number = page_table[page_number];          // one lookup, one entry per page

physical_address = (frame_number * page_size) + offset;

