blocks.content:
// step one, split the logical address into page number and offset

page_size = 4096;              // 4 KB pages
logical_address = 5000;

page_number = logical_address / page_size;   // 5000 divided by 4096 is 1
offset      = logical_address % page_size;   // 5000 modulo 4096 is 904

// page_number is 1, offset is 904

