blocks.content:
// step two, look up the frame number for page 1 in this process page table

page_table[0] = 3;
page_table[1] = 6;
page_table[2] = 2;
page_table[3] = 9;

frame_number = page_table[page_number];   // page_number is 1, so frame_number is 6

// step three, combine the frame number and the offset into the physical address

physical_address = (frame_number * page_size) + offset;
// physical_address = (6 * 4096) + 904
// physical_address = 24576 + 904
// physical_address = 25480

