// second worked example, this time showing internal fragmentation

page_size = 4096;
process_size = 10000;          // total bytes the process actually needs

pages_needed = 3;               // 10000 divided by 4096, rounded up, is 3
last_page_used = 10000-8192;    // process_size minus the first two full pages
// last_page_used = 1808

wasted_in_last_page = 4096-1808;
// wasted_in_last_page = 2288

